class SessionDecisionNfcVerificationsJpkiCertificates(BaseModel):
    """What one certificate read from the card proved. Never the certificate itself or its serial number."""

    type: Literal["user_authentication", "signature"] | str | None = None
    """Which card certificate this entry describes."""

    chain_valid: bool | None = None
    """`true` when the certificate chains to the JPKI certification authority of its type, is inside its validity period and is a My Number Card certificate of that type."""

    signature_valid: bool | None = None
    """`true` when the card's signature over the one-time challenge verifies against this certificate."""

    ca_generation: str | None = None
    """Generation of the JPKI certification authority that issued the certificate, for example `2023`. `null` when no trusted issuer was found."""

    not_valid_before: _dt.datetime | None = None
    """Start of the certificate's validity period. `null` when the certificate could not be read."""

    not_valid_after: _dt.datetime | None = None
    """End of the certificate's validity period. `null` when the certificate could not be read."""

    failure: (
        Literal[
            "unreadable_certificate",
            "untrusted_issuer",
            "expired",
            "not_yet_valid",
            "wrong_policy",
            "key_usage",
        ]
        | str
        | None
    ) = None
    """Why `chain_valid` is `false`: `unreadable_certificate`, `untrusted_issuer` (not issued by the JPKI certification authority of its type), `expired`, `not_yet_valid`, `wrong_policy` (not a My Number Card certificate of that type) or `key_usage` (the key may not sign). `null` when the chain is valid."""


class SessionDecisionNfcVerificationsJpki(BaseModel):
    """What a Japan My Number Card read through JPKI proved. Present when `chip_protocol` is `jpki` and the card was read. `null` for ICAO chips, for skipped steps, and when the NFC step closed without any card read (that case raises `JPKI_SIGNATURE_INVALID`). Never carries the certificates, their serial numbers, the signatures or the 12-digit My Number."""

    certificate_types: list[Literal["user_authentication", "signature"] | str] | None = None
    """The card certificates read. `user_authentication` (4-digit PIN) is always read; `signature` (signature PIN) is read when the NFC node's `jpki_request_attributes` setting is on."""

    chain_valid: bool | None = None
    """`true` when every certificate read chains to the JPKI certification authority, is inside its validity period and is a My Number Card certificate of its type."""

    signature_valid: bool | None = None
    """`true` when every signature the card made over the one-time challenge verifies. The card only signs after its PIN is entered, so this proves possession of the card and knowledge of the PIN."""

    revocation_status: Literal["good", "revoked", "unchecked"] | str | None = None
    """`good` when the revocation check confirmed every certificate is valid, `revoked` when any certificate is revoked (for example a card reported lost), `unchecked` when no revocation answer was available. `unchecked` is never treated as `good`: the NFC node's `jpki_revocation_unchecked_action` decides the outcome (default `REVIEW`)."""

    ca_generation: str | None = None
    """Generation of the JPKI certification authority that issued the certificates, for example `2023`. `null` when no certificate chains to one."""

    certificate_expires_at: _dt.datetime | None = None
    """The earliest expiry among the certificates read."""

    certificates: list[SessionDecisionNfcVerificationsJpkiCertificates] | None = None
    """Per-certificate results, one entry per certificate read."""

    attributes: SessionDecisionNfcVerificationsJpkiAttributes | None = None
    """The holder's data from the signature certificate, once its chain is valid. `null` when the signature certificate was not requested or did not chain to the JPKI certification authority."""

    attributes_match_ocr: bool | None = None
    """`true` when the attributes match the data read from the photo of the same card, `false` when any attribute differs (`JPKI_AND_OCR_DATA_NOT_SAME`), `null` when nothing could be compared, including whenever `attributes` is `null`."""

    mismatched_attributes: (
        list[Literal["full_name", "date_of_birth", "gender", "address"] | str] | None
    ) = None
    """Names of the attributes that differ from the photo data, never their values. Empty when everything compared matches."""


